def solve(stream, registers):
    # Register 0 will keep the count. 
    # Since a register can only hold up to 3, we use Register 1 as a carry.
    registers.set(0, 0)
    registers.set(1, 0)

    for _ in range(4):
        bit = stream.next_bit()
        if bit == 1:
            current_count = registers.get(0)
            if current_count < 3:
                registers.set(0, current_count + 1)
            else:
                # current_count is 3, so total becomes 4.
                # Set R0 to 0 and R1 to 1 (1 * 4 + 0 = 4).
                registers.set(0, 0)
                registers.set(1, registers.get(1) + 1)

    # The total count is R1 * 4 + R0
    return registers.get(1) * 4 + registers.get(0)

